<?php
require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$pageTitle='Change Password';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$_SESSION['user_id']]);$row=$q->fetch();if(!$row||!password_verify($current,$row['password_hash'])){flash('danger','Current password is incorrect.');redirect('change_password.php');}elseif(strlen($new)<10||!preg_match('/[A-Za-z]/',$new)||!preg_match('/[0-9]/',$new)){flash('danger','New password must be at least 10 characters and contain letters and numbers.');redirect('change_password.php');}elseif($new!==$confirm){flash('danger','New password and confirmation do not match.');redirect('change_password.php');}else{$q=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['user_id']]);flash('success','Password changed successfully.');redirect('change_password.php');}}
require __DIR__.'/includes/header.php';
?>
